const path = require('path');
const fs = require('fs');
const { getDeliveryClient } = require('../lib/whatsapp-delivery');

// System channel mappings
const CHANNEL_MAP = {
  daily_report:    { channel: 'whatsapp', template: 'daily_report' },
  health_check:    { channel: 'whatsapp', template: 'health_check' },
  git_backup:      { channel: 'whatsapp', template: 'git_backup' },
  alert:           { channel: 'whatsapp', template: 'alert' },
  system_note:     { channel: 'whatsapp', template: 'system_note' },
};

function dispatch(notification) {
  const config = CHANNEL_MAP[notification.category] || CHANNEL_MAP.system_note;

  if (config.channel === 'whatsapp') {
    const client = getDeliveryClient();
    client.send({
      to: process.env.MOOSA_ADMIN_WHATSAPP,
      body: notification.message,
      metadata: {
        category: notification.category,
        timestamp: notification.timestamp,
        source: notification.source
      }
    });
  }
}

module.exports = { dispatch, CHANNEL_MAP };



Key findings:
• Hardcoded to `whatsapp` delivery only via `whatsapp-delivery.js`
• `CHANNEL_MAP` is the routing table — only entry point for adding channels
• No fan-out/multicast — one notification goes to one channel
• Notification object shape: `{ category, message, timestamp, source }`
• `getDeliveryClient()` is a singleton from `whatsapp-delivery.js`

