javascript
let client = null;

function getDeliveryClient() {
  if (!client) {
    const { Client, LocalAuth } = require('whatsapp-web.js');
    client = new Client({
      puppeteer: { headless: true, args: ['--no-sandbox'] },
      authStrategy: new LocalAuth({ dataPath: '/root/.openclaw/whatsapp-session' })
    });

    client.on('ready', () => console.log('[WhatsApp] Delivery client ready'));
    client.on('message', () => {});
    client.on('error', (err) => console.error('[WhatsApp] Error:', err));
    client.on('disconnected', () => { client = null; });

    client.initialize().catch(console.error);
  }
  return client;
}

function send({ to, body, metadata }) {
  const waClient = getDeliveryClient();
  const paddedNumber = to.replace(/\D/g, '') + '@c.us';
  waClient.sendMessage(paddedNumber, body).catch(err => {
    console.error('[WhatsApp] Send failed:', err.message);
  });
}

module.exports = { getDeliveryClient, send };



Key findings:
• WhatsApp delivery uses `whatsapp-web.js` with `LocalAuth` session
• `send()` is the only outbound method
• No error recovery — silent catch on failures
• No queue or retry logic

