Full contents:


javascript
const express = require('express');
const fs = require('fs');
const path = require('path');
const { fileURLToPath } = require('url');

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const app = express();
const CONVERSATIONS_FILE = path.join(__dirname, 'data/conversations.json');

app.use(express.json());

// ── READ ─────────────────────────────────────────────────────────────────────
function readConversations() {
  try {
    const raw = fs.readFileSync(CONVERSATIONS_FILE, 'utf8');
    const data = JSON.parse(raw);
    // Always normalise to object keyed by conversation_id
    if (Array.isArray(data)) {
      const obj = {};
      data.forEach(conv => { obj[conv.conversation_id] = conv; });
      return obj;
    }
    return data;
  } catch {
    return {};           // Graceful empty state
  }
}

// ── WRITE ────────────────────────────────────────────────────────────────────
function writeConversations(obj) {
  fs.writeFileSync(CONVERSATIONS_FILE, JSON.stringify(obj, null, 2));
}

app.get('/api/conversations', (req, res) => {
  const conversations = readConversations();
  // Always return as array (normalised from object internally)
  res.json(Object.values(conversations));
});

app.post('/api/conversations', (req, res) => {
  const { conversation_id, title, category } = req.body;
  const conversations = readConversations();

  if (conversations[conversation_id]) {
    return res.status(409).json({ error: 'Conversation already exists' });
  }

  conversations[conversation_id] = {
    conversation_id,
    title,
    category,
    messages: [],
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString()
  };

  writeConversations(conversations);
  res.status(201).json(conversations[conversation_id]);
});

app.post('/api/conversations/:id/messages', (req, res) => {
  const { id } = req.params;
  const { sender, text, metadata } = req.body;
  const conversations = readConversations();

  if (!conversations[id]) {
    return res.status(404).json({ error: 'Conversation not found' });
  }

  conversations[id].messages.push({
    sender,
    text,
    metadata,
    timestamp: new Date().toISOString()
  });

  conversations[id].updated_at = new Date().toISOString();
  writeConversations(conversations);
  res.status(201).json({ ok: true });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`MOOSA Web Console running on ${PORT}`));



