// ── WORKER-TO-CONSOLE SYSTEM MESSAGE ENDPOINT ────────────────────────────────
// Local-only. Accepts routed MOOSA routine/health/alert messages from the worker.
// Requires X-MOOSA-SECRET header. Never exposed to browser clients.
// ─────────────────────────────────────────────────────────────────────────────
const WORKER_SECRET = process.env.MOOSA_WORKER_TO_CONSOLE_SECRET || '';

app.post('/api/system-message', (req, res) => {
  // Reject non-local requests
  const remoteIp = req.ip || req.connection.remoteAddress || '';
  const isLocalhost = remoteIp === '127.0.0.1' || remoteIp === '::1' || remoteIp === '::ffff:127.0.0.1';
  if (!isLocalhost) {
    return res.status(403).json({ error: 'Not allowed outside localhost' });
  }

  // Validate secret header
  const providedSecret = req.headers['x-moosa-secret'] || '';
  if (!WORKER_SECRET || providedSecret !== WORKER_SECRET) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  // Parse payload
  const {
    conversation_id,   // string — e.g. "moosa-daily-reports"
    category,          // string — e.g. "daily_report", "health_check"
    sender,            // string — e.g. "MOOSA-Routine"
    text,              // string — the message body
    metadata = {}      // object — timestamp, source, etc.
  } = req.body;

  // Validate required fields
  if (!conversation_id || !text) {
    return res.status(400).json({ error: 'Missing conversation_id or text' });
  }

  try {
    const conversations = readConversations();

    // Create conversation if it does not exist
    if (!conversations[conversation_id]) {
      const titles = {
        daily_report:   '📋 MOOSA Daily Reports',
        health_check:   '🩺 MOOSA Health Checks',
        git_backup:     '🔄 MOOSA Git & Backups',
        alert:          '🚨 MOOSA Alerts & Exceptions',
        system_note:    '🔔 MOOSA System Notifications',
      };

      conversations[conversation_id] = {
        conversation_id,
        title: titles[category] || `MOOSA — ${conversation_id}`,
        category: category || 'system_note',
        messages: [],
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString()
      };
    }

    // Append message — append-only, never modifies old messages
    const message = {
      id: `msg_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      sender: sender || 'MOOSA-System',
      text,
      metadata: {
        ...metadata,
        delivered_via: 'web-console-delivery',
        category
      },
      timestamp: metadata.timestamp || new Date().toISOString()
    };

    conversations[conversation_id].messages.push(message);
    conversations[conversation_id].updated_at = new Date().toISOString();

    writeConversations(conversations);

    return res.status(200).json({
      success: true,
      conversation_id,
      message_id: message.id,
      message_count: conversations[conversation_id].messages.length
    });
  } catch (err) {
    console.error('[worker-delivery] Failed to write system message:', err);
    return res.status(500).json({ error: 'Internal server error' });
  }
});



