const path = require('path');
const { fileURLToPath } = require('url');

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const app = express();
const CONVERSATIONS_FILE = path.join(__dirname, 'data/conversations.json');

// ── Shared secret for worker-to-console delivery ──────────────────────────
const WORKER_SECRET = process.env.MOOSA_WORKER_TO_CONSOLE_SECRET || '';

// ── READ (internal) ───────────────────────────────────────────────────────
function readConversations() {
  try {
    const raw = fs.readFileSync(CONVERSATIONS_FILE, 'utf8');
    const data = JSON.parse(raw);
    if (Array.isArray(data)) {
      const obj = {};
      data.forEach(conv => { obj[conv.conversation_id] = conv; });
      return obj;
    }
    return data;
  } catch {
    return {};
  }
}

// ── WRITE (internal) ──────────────────────────────────────────────────────
function writeConversations(obj) {
  fs.writeFileSync(CONVERSATIONS_FILE, JSON.stringify(obj, null, 2));
}

// ── SYSTEM MESSAGE ENDPOINT (localhost-only, secret-gated) ───────────────
app.post('/api/system-message', (req, res) => {
  // Step 1: Reject non-localhost requests
  const remoteAddr = req.ip || req.connection.remoteAddress || '';
  const isLocalhost = remoteAddr === '127.0.0.1' ||
                      remoteAddr === '::1' ||
                      remoteAddr === '::ffff:127.0.0.1';

  if (!isLocalhost) {
    return res.status(403).json({ error: 'Forbidden: localhost only' });
  }

  // Step 2: Validate secret header
  const secret = req.headers['x-moosa-secret'] || '';
  if (!WORKER_SECRET || secret !== WORKER_SECRET) {
    return res.status(401).json({ error: 'Unauthorized: invalid secret' });
  }

  // Step 3: Parse body
  const { conversation_id, sender, text, metadata } = req.body;
  if (!conversation_id || !text) {
    return res.status(400).json({ error: 'Missing conversation_id or text' });
  }

  // Step 4: Read existing conversations
  const conversations = readConversations();

  // Step 5: Create conversation if missing
  if (!conversations[conversation_id]) {
    const category = metadata?.category || 'system_note';
    conversations[conversation_id] = {
      conversation_id,
      title: metadata?.title || conversation_id,
      category,
      messages: [],
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString()
    };
  }

  // Step 6: Append message
  const messageEntry = {
    id: `msg_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    sender: sender || 'MOOSA-SYSTEM',
    text,
    metadata: metadata || {},
    timestamp: new Date().toISOString()
  };

  conversations[conversation_id].messages.push(messageEntry);
  conversations[conversation_id].updated_at = new Date().toISOString();

  // Step 7: Write back safely
  writeConversations(conversations);

  console.log(`[system-message] ✓ Delivered to ${conversation_id}: ${text.substring(0, 60)}...`);

  res.status(201).json({
    success: true,
    conversation_id,
    message_id: messageEntry.id,
    timestamp: messageEntry.timestamp
  });
});

// ── Existing routes (unchanged) ──────────────────────────────────────────
app.use(express.json());

app.get('/api/conversations', (req, res) => {
  const conversations = readConversations();
  res.json(Object.values(conversations));
});

app.post('/api/conversations', (req, res) => {
  const { conversation_id, title, category } = req.body;
  const conversations = readConversations();

  if (conversations[conversation_id]) {
    return res.status(409).json({ error: 'Conversation already exists' });
  }

  conversations[conversation_id] = {
    conversation_id,
    title,
    category,
    messages: [],
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString()
  };

  writeConversations(conversations);
  res.status(201).json(conversations[conversation_id]);
});

const PORT = process.env.PORT || 3099;
app.listen(PORT, () => {
  console.log(`MOOSA Web Console running on port ${PORT}`);
});
